import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.geom.AffineTransform;
import java.util.*;
import java.util.List;
import java.util.prefs.Preferences;

public class wordle extends JFrame {

    static final Color BG = new Color(0x1a0b2e);
    static final Color PANEL = new Color(0x2a1650);
    static final Color EMPTY_BORDER = new Color(0x3d2468);
    static final Color FILLED_BORDER = new Color(0xa78bca);
    static final Color CORRECT = new Color(0xa855f7);
    static final Color PRESENT = new Color(0xec4899);
    static final Color ABSENT = new Color(0x2c2140);
    static final Color KEY = new Color(0x5b3a8f);
    static final Color KEY_HOVER = new Color(0x7048ad);
    static final Color TEXT = new Color(0xf3e8ff);
    static final Color MUTED = new Color(0xa78bca);
    static final Color ACCENT = new Color(0xc084fc);
    static final Color BTN = new Color(0x7c3aed);
    static final Color BTN_HOVER = new Color(0x9b6bff);
    static final String FONT = "SansSerif";

    static final int TILE = 48, GAP = 6, PAD = 14;
    static final int GRID_W = 5 * TILE + 4 * GAP, GRID_H = 6 * TILE + 5 * GAP;
    static final int KEY_W = 31, KEY_H = 44, KEY_GAP = 5;
    static final int KB_W = 10 * KEY_W + 9 * KEY_GAP;
    static final int W = PAD * 2 + KB_W;
    static final int HEADER = 40;
    static final int GRID_Y = PAD + HEADER;
    static final int KB_Y = GRID_Y + GRID_H + 18;
    static final int H = KB_Y + 3 * KEY_H + 2 * KEY_GAP + PAD;

    static final String ANSWERS = "";
    static final String[] GUESSES = {
            "",
            ""
    };
    static final Set<String> VALID = new HashSet<>();
    static final List<String> ANSWER_LIST = new ArrayList<>();
    static {
        for (int i = 0; i < ANSWERS.length(); i += 5) {
            String w = ANSWERS.substring(i, i + 5);
            ANSWER_LIST.add(w);
            VALID.add(w);
        }
        for (String chunk : GUESSES)
            for (int i = 0; i < chunk.length(); i += 5) VALID.add(chunk.substring(i, i + 5));
    }

    Game game;

    public wordle() {
        super("Wordle");
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        setResizable(false);
        Game g = new Game();
        game = g;
        setContentPane(g);
        pack();
        setLocationRelativeTo(null);
        addWindowFocusListener(new WindowAdapter() {
            public void windowGainedFocus(WindowEvent e) { g.requestFocusInWindow(); }
        });
    }

    static int[] evaluate(String guess, String answer) {
        int[] res = new int[5];
        int[] left = new int[26];
        for (int i = 0; i < 5; i++) {
            if (guess.charAt(i) == answer.charAt(i)) res[i] = 2;
            else left[answer.charAt(i) - 'a']++;
        }
        for (int i = 0; i < 5; i++) {
            if (res[i] == 2) continue;
            int c = guess.charAt(i) - 'a';
            if (left[c] > 0) { res[i] = 1; left[c]--; }
        }
        return res;
    }

    static class Game extends JPanel {
        static final String[] ROWS_KB = {"qwertyuiop", "asdfghjkl", "<zxcvbnm>"};
        static final String[] WIN_MSG = {"GÊNIA ABSOLUTA! ♛", "ICÔNICA! ♛", "ARRASOU, DIVA!", "SLAY! ♥", "MANDOU BEM!", "UFA, NO LIMITE!"};

        final Preferences prefs = tryPrefs();
        final List<String> deck = new ArrayList<>(ANSWER_LIST);
        int deckPos = 0;

        String answer;
        final String[] guesses = new String[6];
        final int[][] results = new int[6][];
        String typing = "";
        int row = 0;
        boolean over = false, won = false;
        final int[] keyState = new int[26];

        int played, wins, streak, bestStreak;
        final int[] dist = new int[6];

        long revealStart = -1; int revealRow = -1;
        static final int FLIP_MS = 280, STAGGER = 260;
        long shakeStart = -1;
        long popStart = -1; int popCol = -1;
        String toast = null; long toastUntil = 0;
        long overlayAt = 0;

        final Map<Character, Rectangle> keyRects = new LinkedHashMap<>();
        final Rectangle button = new Rectangle();
        Character hoverKey = null; boolean hoverBtn = false;

        final javax.swing.Timer anim = new javax.swing.Timer(16, e -> repaint());

        Game() {
            setPreferredSize(new Dimension(W, H));
            setBackground(BG);
            setFocusable(true);
            loadStats();
            Collections.shuffle(deck);
            layoutKeys();
            newWord();

            addKeyListener(new KeyAdapter() {
                public void keyPressed(KeyEvent e) {
                    int k = e.getKeyCode();
                    if (k == KeyEvent.VK_ENTER) press('<');
                    else if (k == KeyEvent.VK_BACK_SPACE || k == KeyEvent.VK_DELETE) press('>');
                    else {
                        char c = Character.toLowerCase(e.getKeyChar());
                        if (c >= 'a' && c <= 'z') press(c);
                    }
                }
            });
            MouseAdapter m = new MouseAdapter() {
                public void mouseMoved(MouseEvent e) {
                    Character hk = null;
                    if (!showOverlay())
                        for (Map.Entry<Character, Rectangle> en : keyRects.entrySet())
                            if (en.getValue().contains(e.getPoint())) hk = en.getKey();
                    boolean hb = showOverlay() && button.contains(e.getPoint());
                    if (!Objects.equals(hk, hoverKey) || hb != hoverBtn) { hoverKey = hk; hoverBtn = hb; repaint(); }
                    setCursor(Cursor.getPredefinedCursor(hk != null || hb ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
                }
                public void mousePressed(MouseEvent e) {
                    requestFocusInWindow();
                    if (showOverlay()) {
                        if (button.contains(e.getPoint())) newWord();
                        return;
                    }
                    for (Map.Entry<Character, Rectangle> en : keyRects.entrySet())
                        if (en.getValue().contains(e.getPoint())) press(en.getKey());
                }
            };
            addMouseListener(m);
            addMouseMotionListener(m);
            anim.start();
        }

        static Preferences tryPrefs() {
            try { return Preferences.userRoot().node("wordle-diva"); } catch (Exception e) { return null; }
        }

        void loadStats() {
            if (prefs == null) return;
            played = prefs.getInt("played", 0); wins = prefs.getInt("wins", 0);
            streak = prefs.getInt("streak", 0); bestStreak = prefs.getInt("best", 0);
            for (int i = 0; i < 6; i++) dist[i] = prefs.getInt("d" + i, 0);
        }

        void saveStats() {
            if (prefs == null) return;
            try {
                prefs.putInt("played", played); prefs.putInt("wins", wins);
                prefs.putInt("streak", streak); prefs.putInt("best", bestStreak);
                for (int i = 0; i < 6; i++) prefs.putInt("d" + i, dist[i]);
            } catch (Exception ignored) {}
        }

        void layoutKeys() {
            for (int r = 0; r < 3; r++) {
                String s = ROWS_KB[r];
                int wide = (int) (KEY_W * 1.5 + KEY_GAP / 2.0);
                int total = 0;
                for (char c : s.toCharArray()) total += (c == '<' || c == '>' ? wide : KEY_W) + KEY_GAP;
                total -= KEY_GAP;
                int x = (W - total) / 2, y = KB_Y + r * (KEY_H + KEY_GAP);
                for (char c : s.toCharArray()) {
                    int w = c == '<' || c == '>' ? wide : KEY_W;
                    keyRects.put(c, new Rectangle(x, y, w, KEY_H));
                    x += w + KEY_GAP;
                }
            }
        }

        void newWord() {
            if (deckPos >= deck.size()) { Collections.shuffle(deck); deckPos = 0; }
            answer = deck.get(deckPos++);
            Arrays.fill(guesses, null);
            Arrays.fill(results, null);
            Arrays.fill(keyState, -1);
            typing = ""; row = 0; over = false; won = false;
            revealRow = -1; toast = null; hoverBtn = false;
            repaint();
        }

        boolean revealing() {
            return revealRow >= 0 && System.currentTimeMillis() - revealStart < 4 * STAGGER + FLIP_MS;
        }

        boolean showOverlay() {
            return over && !revealing() && System.currentTimeMillis() >= overlayAt;
        }

        void press(char c) {
            if (over) {
                if (c == '<' && showOverlay()) newWord();
                return;
            }
            if (revealing()) return;
            if (c == '<') submit();
            else if (c == '>') { if (!typing.isEmpty()) typing = typing.substring(0, typing.length() - 1); }
            else if (typing.length() < 5) {
                typing += c;
                popCol = typing.length() - 1; popStart = System.currentTimeMillis();
            }
            repaint();
        }

        void say(String msg, int ms) { toast = msg; toastUntil = System.currentTimeMillis() + ms; }

        void submit() {
            if (typing.length() < 5) { say("Faltam letras, diva!", 1300); shakeStart = System.currentTimeMillis(); return; }
            if (!VALID.contains(typing)) { say("Essa palavra não existe!", 1300); shakeStart = System.currentTimeMillis(); return; }

            int[] res = evaluate(typing, answer);
            guesses[row] = typing;
            results[row] = res;
            revealRow = row; revealStart = System.currentTimeMillis();
            for (int i = 0; i < 5; i++) {
                int ci = typing.charAt(i) - 'a';
                keyState[ci] = Math.max(keyState[ci], res[i]);
            }
            boolean hit = typing.equals(answer);
            row++;
            typing = "";
            long revealEnd = revealStart + 4 * STAGGER + FLIP_MS;
            if (hit || row == 6) {
                over = true; won = hit;
                played++;
                if (hit) { wins++; streak++; bestStreak = Math.max(bestStreak, streak); dist[row - 1]++; }
                else streak = 0;
                saveStats();
                overlayAt = revealEnd + (hit ? 900 : 1300);
                javax.swing.Timer t = new javax.swing.Timer((int) (revealEnd - System.currentTimeMillis()), e -> {
                    say(hit ? WIN_MSG[row - 1] : answer.toUpperCase(), hit ? 900 : 1300);
                });
                t.setRepeats(false); t.start();
            }
        }

        @Override protected void paintComponent(Graphics g0) {
            super.paintComponent(g0);
            Graphics2D g = (Graphics2D) g0.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            long now = System.currentTimeMillis();

            g.setFont(new Font(FONT, Font.BOLD, 22));
            FontMetrics fm = g.getFontMetrics();
            String a = "Wordle ", b = "Diva";
            int tx = (W - fm.stringWidth(a + b)) / 2;
            g.setColor(ACCENT); g.drawString(a, tx, PAD + 24);
            g.setColor(TEXT); g.drawString(b, tx + fm.stringWidth(a), PAD + 24);
            g.setFont(new Font(FONT, Font.BOLD, 12));
            g.setColor(MUTED);
            g.drawString("♛ " + streak, W - PAD - 34, PAD + 22);

            int gx = (W - GRID_W) / 2;
            for (int r = 0; r < 6; r++) {
                int shake = 0;
                if (r == row && !over && shakeStart > 0 && now - shakeStart < 400) {
                    double t = (now - shakeStart) / 400.0;
                    shake = (int) (Math.sin(t * Math.PI * 6) * 8 * (1 - t));
                }
                for (int c = 0; c < 5; c++) {
                    int x = gx + c * (TILE + GAP) + shake, y = GRID_Y + r * (TILE + GAP);
                    char ch = 0; int state = -1;
                    if (guesses[r] != null) { ch = guesses[r].charAt(c); state = results[r][c]; }
                    else if (r == row && c < typing.length()) ch = typing.charAt(c);

                    double scaleY = 1; boolean showColor = state >= 0;
                    if (state >= 0 && r == revealRow) {
                        long t = now - revealStart - c * STAGGER;
                        if (t < 0) showColor = false;
                        else if (t < FLIP_MS) {
                            double p = t / (double) FLIP_MS;
                            scaleY = Math.abs(Math.cos(p * Math.PI));
                            showColor = p >= 0.5;
                        }
                    }
                    double scale = 1;
                    if (r == row && c == popCol && now - popStart < 110) scale = 1 + 0.1 * Math.sin((now - popStart) / 110.0 * Math.PI);
                    int bounce = 0;
                    if (won && r == row - 1 && revealRow == r) {
                        long t = now - (revealStart + 4 * STAGGER + FLIP_MS) - c * 90;
                        if (t > 0 && t < 350) bounce = (int) (-Math.sin(t / 350.0 * Math.PI) * 14);
                    }

                    AffineTransform old = g.getTransform();
                    g.translate(x + TILE / 2.0, y + TILE / 2.0 + bounce);
                    g.scale(scale, scale * Math.max(scaleY, 0.02));
                    int h = TILE / 2;
                    if (showColor) {
                        g.setColor(state == 2 ? CORRECT : state == 1 ? PRESENT : ABSENT);
                        g.fillRoundRect(-h, -h, TILE, TILE, 10, 10);
                    } else {
                        g.setColor(BG);
                        g.fillRoundRect(-h, -h, TILE, TILE, 10, 10);
                        g.setColor(ch != 0 ? FILLED_BORDER : EMPTY_BORDER);
                        g.setStroke(new BasicStroke(2));
                        g.drawRoundRect(-h + 1, -h + 1, TILE - 2, TILE - 2, 10, 10);
                    }
                    if (ch != 0) {
                        g.setFont(new Font(FONT, Font.BOLD, 24));
                        g.setColor(TEXT);
                        String s = String.valueOf(Character.toUpperCase(ch));
                        FontMetrics f2 = g.getFontMetrics();
                        g.drawString(s, -f2.stringWidth(s) / 2, (f2.getAscent() - f2.getDescent()) / 2);
                    }
                    g.setTransform(old);
                }
            }

            int[] shown = keyStatesShown(now);
            for (Map.Entry<Character, Rectangle> en : keyRects.entrySet()) {
                char c = en.getKey(); Rectangle r = en.getValue();
                Color col = KEY;
                if (c >= 'a' && c <= 'z') {
                    int st = shown[c - 'a'];
                    if (st == 2) col = CORRECT; else if (st == 1) col = PRESENT; else if (st == 0) col = ABSENT;
                }
                if (Objects.equals(hoverKey, c)) col = st(col);
                g.setColor(col);
                g.fillRoundRect(r.x, r.y, r.width, r.height, 9, 9);
                boolean dead = c >= 'a' && c <= 'z' && shown[c - 'a'] == 0;
                g.setColor(dead ? new Color(0x6f5a90) : TEXT);
                if (c == '>') { backspaceIcon(g, r); continue; }
                String label = c == '<' ? "ENTER" : String.valueOf(Character.toUpperCase(c));
                g.setFont(new Font(FONT, Font.BOLD, c == '<' ? 10 : c == '>' ? 16 : 15));
                FontMetrics f3 = g.getFontMetrics();
                g.drawString(label, r.x + (r.width - f3.stringWidth(label)) / 2,
                        r.y + (r.height + f3.getAscent() - f3.getDescent()) / 2);
            }

            if (toast != null && now < toastUntil) {
                g.setFont(new Font(FONT, Font.BOLD, 14));
                FontMetrics f4 = g.getFontMetrics();
                int tw = f4.stringWidth(toast) + 28, th = 34;
                int x = (W - tw) / 2, y = PAD + 3;
                g.setColor(TEXT);
                g.fillRoundRect(x, y, tw, th, 12, 12);
                g.setColor(BG);
                g.drawString(toast, x + 14, y + (th + f4.getAscent() - f4.getDescent()) / 2);
            }

            if (showOverlay()) drawOverlay(g);
            g.dispose();
        }

        static void backspaceIcon(Graphics2D g, Rectangle r) {
            int cx = r.x + r.width / 2, cy = r.y + r.height / 2;
            int[] xs = {cx - 12, cx - 5, cx + 11, cx + 11, cx - 5};
            int[] ys = {cy, cy - 8, cy - 8, cy + 8, cy + 8};
            g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.drawPolygon(xs, ys, 5);
            g.drawLine(cx - 1, cy - 4, cx + 7, cy + 4);
            g.drawLine(cx + 7, cy - 4, cx - 1, cy + 4);
        }

        static Color st(Color c) {
            return new Color(Math.min(255, c.getRed() + 22), Math.min(255, c.getGreen() + 22), Math.min(255, c.getBlue() + 22));
        }

        int[] keyStatesShown(long now) {
            if (!revealing()) return keyState;
            int[] s = new int[26];
            Arrays.fill(s, -1);
            for (int r = 0; r < row; r++) {
                for (int c = 0; c < 5; c++) {
                    if (r == revealRow && now - revealStart - c * STAGGER < FLIP_MS / 2) continue;
                    int ci = guesses[r].charAt(c) - 'a';
                    s[ci] = Math.max(s[ci], results[r][c]);
                }
            }
            return s;
        }

        void drawOverlay(Graphics2D g) {
            g.setColor(new Color(20, 8, 36, 215));
            g.fillRect(0, 0, W, H);
            int cw = W - 40, ch = 360, cx = 20, cy = (H - ch) / 2;
            g.setColor(PANEL);
            g.fillRoundRect(cx, cy, cw, ch, 20, 20);
            g.setColor(new Color(0x4c1d95));
            g.setStroke(new BasicStroke(2));
            g.drawRoundRect(cx, cy, cw, ch, 20, 20);

            int y = cy + 38;
            g.setFont(new Font(FONT, Font.BOLD, 20));
            g.setColor(ACCENT);
            centered(g, won ? WIN_MSG[row - 1] : "Não foi dessa vez ♥", y);
            y += 26;
            g.setFont(new Font(FONT, Font.PLAIN, 13));
            g.setColor(MUTED);
            centered(g, "A palavra era", y);
            y += 8;
            int t = 30, gap = 5, wx = (W - (5 * t + 4 * gap)) / 2;
            for (int i = 0; i < 5; i++) {
                g.setColor(CORRECT);
                g.fillRoundRect(wx + i * (t + gap), y, t, t, 7, 7);
                g.setColor(TEXT);
                g.setFont(new Font(FONT, Font.BOLD, 17));
                String s = String.valueOf(Character.toUpperCase(answer.charAt(i)));
                FontMetrics f = g.getFontMetrics();
                g.drawString(s, wx + i * (t + gap) + (t - f.stringWidth(s)) / 2, y + (t + f.getAscent() - f.getDescent()) / 2);
            }
            y += t + 26;

            String[][] stats = {
                    {String.valueOf(played), "jogos"},
                    {played == 0 ? "0" : String.valueOf(Math.round(100.0 * wins / played)), "% vitórias"},
                    {String.valueOf(streak), "sequência"},
                    {String.valueOf(bestStreak), "recorde"}};
            int colW = (cw - 20) / 4;
            for (int i = 0; i < 4; i++) {
                int sx = cx + 10 + i * colW;
                g.setFont(new Font(FONT, Font.BOLD, 20));
                g.setColor(TEXT);
                FontMetrics f = g.getFontMetrics();
                g.drawString(stats[i][0], sx + (colW - f.stringWidth(stats[i][0])) / 2, y);
                g.setFont(new Font(FONT, Font.PLAIN, 10));
                g.setColor(MUTED);
                f = g.getFontMetrics();
                g.drawString(stats[i][1], sx + (colW - f.stringWidth(stats[i][1])) / 2, y + 14);
            }
            y += 30;

            int max = 1;
            for (int d : dist) max = Math.max(max, d);
            int barX = cx + 34, barMax = cw - 34 - 26;
            for (int i = 0; i < 6; i++) {
                g.setFont(new Font(FONT, Font.BOLD, 11));
                g.setColor(TEXT);
                g.drawString(String.valueOf(i + 1), cx + 20, y + 12);
                int bw = Math.max(22, (int) (barMax * dist[i] / (double) max));
                g.setColor(won && i == row - 1 ? CORRECT : ABSENT);
                g.fillRoundRect(barX, y, bw, 16, 5, 5);
                g.setColor(TEXT);
                String n = String.valueOf(dist[i]);
                g.drawString(n, barX + bw - g.getFontMetrics().stringWidth(n) - 6, y + 12);
                y += 20;
            }
            y += 10;

            int bw = 190, bh = 40;
            button.setBounds((W - bw) / 2, y, bw, bh);
            g.setColor(hoverBtn ? BTN_HOVER : BTN);
            g.fillRoundRect(button.x, button.y, bw, bh, 14, 14);
            g.setFont(new Font(FONT, Font.BOLD, 15));
            g.setColor(TEXT);
            FontMetrics f = g.getFontMetrics();
            String s = "Próxima palavra";
            g.drawString(s, button.x + (bw - f.stringWidth(s)) / 2, button.y + (bh + f.getAscent() - f.getDescent()) / 2);
        }

        static void centered(Graphics2D g, String s, int baseline) {
            g.drawString(s, (W - g.getFontMetrics().stringWidth(s)) / 2, baseline);
        }
    }

    public void hubStart() { game.requestFocusInWindow(); }
    public void hubResume() { game.requestFocusInWindow(); }
    public void hubStop() { game.anim.stop(); }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            wordle w = new wordle();
            w.setVisible(true);
            w.getContentPane().requestFocusInWindow();
        });
    }
}